72: /** Metrics are cumulative within the current run. Reject decreases instead of silently resetting usage. */
73: export function updateRun(state: SessionExecutionState, patch: RunProgress): RunState {
74:   const run = currentRun(state);
75:   if (!isActiveRun(run)) throw new Error('当前运行已经结束。');
76:   for (const key of ['turns', 'toolCalls'] as const) if (patch[key] !== undefined) {
77:     nonnegative(patch[key], key);
78:     if (patch[key] < run[key]) throw new Error(`${key} 不能倒退。`);
79:   }
80:   const usage = { ...run.usage, ...patch.usage, estimated: run.usage.estimated || patch.usage?.estimated === true };
81:   for (const key of ['tokens', 'inputTokens', 'outputTokens', 'cachedInputTokens'] as const) if (usage[key] !== undefined) {
82:     nonnegative(usage[key], key);
83:     if (run.usage[key] !== undefined && usage[key] < run.usage[key]) throw new Error(`${key} 不能倒退。`);
84:   }
85:   if (patch.checkpoint !== undefined && !patch.checkpoint.trim()) throw new Error('检查点不能为空。');
86:   if (patch.turns !== undefined) run.turns = patch.turns;
87:   if (patch.toolCalls !== undefined) run.toolCalls = patch.toolCalls;
88:   run.usage = usage;
89:   if (patch.checkpoint !== undefined) run.checkpoint = patch.checkpoint;
90:   if (patch.status) { run.status = patch.status; requireTask(state).status = patch.status; }
91:   run.updatedAt = now(); return run;
92: }
