{"newText":"export type SessionStatus = 'running' | 'awaiting_approval' | 'cancelled' | 'limited' | 'failed' | 'answered' | 'verified' | 'interrupted' | 'legacy';
export interface SessionListOptions { cwd?: string; status?: SessionStatus | string }

const sessionStatuses = new Set<SessionStatus>(['running', 'awaiting_approval', 'cancelled', 'limited', 'failed', 'answered', 'verified', 'interrupted', 'legacy']);

/** Read-only discovery: listing never acquires locks, migrates, or recovers a session. */
export async function listSessions(home: string, options: SessionListOptions = {}): Promise<SessionSummary[]> {
  if (options.status !== undefined && !sessionStatuses.has(options.status as SessionStatus)) throw new Error(`未知会话状态：${options.status}`);
  const wantedCwd = options.cwd === undefined ? undefined : path.resolve(options.cwd);
  let entries;
  try { entries = await readdir(path.join(home, 'sessions'), { withFileTypes: true }); }
  catch (error) { if ((error as NodeJS.ErrnoException).code === 'ENOENT') return []; throw error; }
  const summaries = await Promise.all(entries.filter(e => e.isDirectory() && sessionIdSchema.safeParse(e.name).success).map(async entry => {
    try {
      const data = parseSessionData(JSON.parse(await readFile(path.join(home, 'sessions', entry.name, 'session.json'), 'utf8')), entry.name);
      const task = 'task' in data ? data.task as { goal?: string; status?: string } | undefined : undefined;
      const status = task?.status ?? 'legacy';
      if (wantedCwd !== undefined && data.cwd !== wantedCwd) return undefined;
      if (options.status !== undefined && status !== options.status) return undefined;
      const first = data.messages.find(m => m.role === 'user');
      return { id: data.id, cwd: data.cwd, model: data.model, provider: data.provider, updatedAt: data.updatedAt, goal: redact(task?.goal ?? first?.content ?? '').replace(/\s+/g, ' ').slice(0, 120), status };
    } catch (error) { if (wantedCwd !== undefined || options.status !== undefined) return undefined; return { id: entry.name, error: redact(errorText(error)).slice(0, 240) }; }
  }));
  const safe: SessionSummary[] = JSON.parse(JSON.stringify(summaries.filter((summary): summary is SessionSummary => summary !== undefined), (_key, value) => typeof value === 'string' ? redact(value) : value));
  return safe.sort((a, b) => (b.updatedAt ?? '').localeCompare(a.updatedAt ?? '') || a.id.localeCompare(b.id));
