{"content":"import { mkdtemp, mkdir, writeFile, readFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { describe, expect, it } from 'vitest';
import { listSessions } from '../src/sessions/list.js';

const snapshot = (id: string, cwd: string, status?: string) => ({ version: 1, id, cwd, provider: 'responses', model: 'test', baseUrl: 'https://example.test/v1', updatedAt: '2024-01-01T00:00:00.000Z', messages: [{ role: 'user', content: 'goal' }], ...(status ? { task: { id: 'task', goal: 'goal', status, remaining: [], completed: [], mutationRevision: 0, verificationChecks: [], verificationRecords: [] } } : {}) });

async function fixture() {
  const home = await mkdtemp(path.join(tmpdir(), 'icy-session-filter-'));
  await mkdir(path.join(home, 'sessions'), { recursive: true });
  for (const [id, data] of [['one', snapshot('one', '/tmp/work', 'answered')], ['two', snapshot('two', '/tmp/other', 'answered')], ['legacy', snapshot('legacy', '/tmp/work')]] as const) {
    await mkdir(path.join(home, 'sessions', id));
    await writeFile(path.join(home, 'sessions', id, 'session.json'), JSON.stringify(data));
  }
  await mkdir(path.join(home, 'sessions', 'broken'));
  await writeFile(path.join(home, 'sessions', 'broken', 'session.json'), '{bad');
  return home;
}

describe('session filters', () => {
  it('combines cwd and status, includes legacy, and excludes bad snapshots when filtered', async () => {
    const home = await fixture();
    expect((await listSessions(home, { cwd: '/tmp/work', status: 'answered' })).map(s => s.id)).toEqual(['one']);
    expect((await listSessions(home, { status: 'legacy' })).map(s => s.id)).toEqual(['legacy']);
    expect((await listSessions(home)).find(s => s.id === 'broken')?.error).toBeTruthy();
    expect((await listSessions(home, { cwd: '/tmp/work' })).find(s => s.id === 'broken')).toBeUndefined();
  });

  it('rejects unknown statuses without touching snapshots', async () => {
    const home = await fixture();
    const before = await readFile(path.join(home, 'sessions', 'one', 'session.json'), 'utf8');
    await expect(listSessions(home, { status: 'nope' })).rejects.toThrow();
    expect(await readFile(path.join(home, 'sessions', 'one', 'session.json'), 'utf8')).toBe(before);
  });
});
